import{_ as o,o as a,c as s,a3 as t}from"./chunks/framework.CZHI6U0G.js";const m=JSON.parse('{"title":"Release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),r={name:"explanation/release-model.md"};function i(c,e,d,l,n,h){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="release-model" tabindex="-1">Release model <a class="header-anchor" href="#release-model" aria-label="Permalink to &quot;Release model&quot;">​</a></h1><blockquote><p>User-facing install is the tamias pack (<code>libraries/myco</code> → <code>tamias install 9aia:myco@&lt;ver&gt;</code>); the <code>myco</code> crates are lib-only engines behind <code>tamias-driver-myco</code> — there is no cargo-installed <code>myco</code> binary and <strong>no crates.io publish</strong> (org policy keeps every repo but tamias off crates.io; the <code>myco</code> name there is held by an unrelated project, and path deps like <code>myco-store-md</code> were never published). This page describes the tag release pipeline that feeds the pack.</p></blockquote><p>Releases are manual: an operator on <code>main</code> runs <code>tarsi-serve release --dir .</code> — dry-run by default, <code>--yes</code> as the explicit opt-in. The per-repo <code>scripts/release.sh</code> shim was removed org-wide; the command talks to tarsi directly.</p><p>The org release plane is <strong>tarsi</strong> (<code>tarsi-serve</code> ops — project ADR-0005); repo policy lives in <code>tarsi.toml</code>.</p><h2 id="what-a-release-run-does" tabindex="-1">What a release run does <a class="header-anchor" href="#what-a-release-run-does" aria-label="Permalink to &quot;What a release run does&quot;">​</a></h2><p><code>tarsi-serve release</code> composes the pipeline — plan → changelog → bump → tag → push — over <code>tarsi.toml</code>:</p><ol><li><strong>Plan</strong> — commits since the last <code>myco-v*</code> tag are classified (conventional commits) and attributed to release units; the workspace shares one version, so the plan is a single-unit lockstep bump. No release-worthy changes, no release.</li><li><strong>Bump</strong> — manifests, <code>Cargo.lock</code>, and the user-facing version refs (<code>libraries/myco/tamias.yaml</code>, the install examples in <code>README.md</code> and <code>.agents/skills/myco/SKILL.md</code>) are rewritten inside the release commit via <code>[release.sync_refs]</code> — the tagged tree is self-consistent.</li><li><strong>Tag + push</strong> — one release commit tagged <code>myco-v&lt;ver&gt;</code>, pushed to <code>main</code> with the tag.</li><li><strong>Pack publish (operator)</strong> — after the tag the operator runs <code>tamias publish libraries/myco</code> to ship <code>9aia:myco@&lt;ver&gt;</code> to the org registry. That step is deliberately outside the release — publishing is a credentials-gated, registry-side action.</li></ol><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li>There is no crates.io publish path and no per-crate tag scheme — the whole workspace shares one version and one <code>myco-v&lt;ver&gt;</code> tag.</li><li>Only the tamias pack is user-facing; <code>myco-tui</code>&#39;s standalone binary and <code>tamias-driver-myco</code> are dev conveniences installed via <code>cargo xtask install</code>, not release artifacts.</li><li>Prebuilt binary distribution (GitHub Releases + cargo-dist — <code>dist-workspace.toml</code> is configured but idle) is a future option tracked as T-041, not part of the release flow.</li></ul><h2 id="ci-and-docs-deploys" tabindex="-1">CI and docs deploys <a class="header-anchor" href="#ci-and-docs-deploys" aria-label="Permalink to &quot;CI and docs deploys&quot;">​</a></h2><p>There are no GitHub Actions workflows; the gate is the peregrin <code>ci-gate</code> campaign (the gate is mid-migration back to bupha):</p><ul><li><strong>Push to <code>docs</code></strong> runs <code>scripts/deploy-docs.sh</code>, which rebuilds the site and pushes <code>gh-pages</code> — Pages is a legacy branch deploy, so that push is the whole release of the site.</li><li><strong>Push to <code>main</code></strong> is gated by the ci-gate campaign (<code>scripts/ci.sh</code> = <code>check &amp;&amp; test</code> + the coverage floor) and locally by the <code>pre-push</code> hook (<code>cargo xtask check</code>).</li></ul>',12)])])}const g=o(r,[["render",i]]);export{m as __pageData,g as default};
